with feeders as (
    select
        md5(upper('HUB_PRODUCT|' || (HUB_PRODUCT_BK__PD_PRODUCT_CODE))) as HUB_PRODUCT_HK
        , PLAN_OPTION as PRODUCT_DISPLAY_NAME
        , PLAN_NAME as PRODUCT_NAME
        , cast(null as varchar) as LINE_OF_BUSINESS
        , cast(null as varchar) as PRODUCT_CATEGORY
        , cast(null as varchar) as PRODUCT_DESCRIPTION
        , cast(null as varchar) as PRODUCT_STATUS
        , cast(null as varchar) as UIN
        , 'BA_HCP_PROD_8433_FHC_LOADER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_prod_8433_fhc_loader') }}
    where (nullif(trim(PD_PRODUCT_CODE),'')) is not null
    union all
    select
        md5(upper('HUB_PRODUCT|' || (HUB_PRODUCT_BK__PD_PRODUCT_CODE))) as HUB_PRODUCT_HK
        , PLAN_OPTION as PRODUCT_DISPLAY_NAME
        , PLAN_NAME as PRODUCT_NAME
        , cast(null as varchar) as LINE_OF_BUSINESS
        , cast(null as varchar) as PRODUCT_CATEGORY
        , cast(null as varchar) as PRODUCT_DESCRIPTION
        , cast(null as varchar) as PRODUCT_STATUS
        , cast(null as varchar) as UIN
        , 'BA_HCP_PROD_8439_CLH_LOADER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_prod_8439_clh_loader') }}
    where (nullif(trim(PD_PRODUCT_CODE),'')) is not null
    union all
    select
        md5(upper('HUB_PRODUCT|' || (HUB_PRODUCT_BK__SCHEME_CODE))) as HUB_PRODUCT_HK
        , cast(null as varchar) as PRODUCT_DISPLAY_NAME
        , SCHEME_DESC as PRODUCT_NAME
        , HEALTH_PRODUCT as LINE_OF_BUSINESS
        , cast(null as varchar) as PRODUCT_CATEGORY
        , cast(null as varchar) as PRODUCT_DESCRIPTION
        , cast(null as varchar) as PRODUCT_STATUS
        , cast(null as varchar) as UIN
        , 'BJAZ_CTNGY_SCHEME_MST' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ctngy_scheme_mst') }}
    where (nullif(trim(SCHEME_CODE),'')) is not null
    union all
    select
        md5(upper('HUB_PRODUCT|' || (HUB_PRODUCT_BK__PRODUCT))) as HUB_PRODUCT_HK
        , cast(null as varchar) as PRODUCT_DISPLAY_NAME
        , PRODUCT_NAME as PRODUCT_NAME
        , cast(null as varchar) as LINE_OF_BUSINESS
        , CATEGORY as PRODUCT_CATEGORY
        , cast(null as varchar) as PRODUCT_DESCRIPTION
        , cast(null as varchar) as PRODUCT_STATUS
        , cast(null as varchar) as UIN
        , 'BJAZ_GRP_HLT_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_grp_hlt_dtls') }}
    where (nullif(trim(PRODUCT),'')) is not null
    union all
    select
        md5(upper('HUB_PRODUCT|' || (HUB_PRODUCT_BK__PRODUCT_CODE))) as HUB_PRODUCT_HK
        , cast(null as varchar) as PRODUCT_DISPLAY_NAME
        , PLAN_NAME as PRODUCT_NAME
        , cast(null as varchar) as LINE_OF_BUSINESS
        , cast(null as varchar) as PRODUCT_CATEGORY
        , cast(null as varchar) as PRODUCT_DESCRIPTION
        , cast(null as varchar) as PRODUCT_STATUS
        , cast(null as varchar) as UIN
        , 'BJAZ_HCS_PLANSI_MAPP' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcs_plansi_mapp') }}
    where (nullif(trim(PRODUCT_CODE),'')) is not null
    union all
    select
        md5(upper('HUB_PRODUCT|' || (HUB_PRODUCT_BK__PRODUCT_4DIGIT_CODE))) as HUB_PRODUCT_HK
        , cast(null as varchar) as PRODUCT_DISPLAY_NAME
        , cast(null as varchar) as PRODUCT_NAME
        , cast(null as varchar) as LINE_OF_BUSINESS
        , cast(null as varchar) as PRODUCT_CATEGORY
        , PLAN_DESC as PRODUCT_DESCRIPTION
        , cast(null as varchar) as PRODUCT_STATUS
        , cast(null as varchar) as UIN
        , 'BJAZ_HG_POL_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hg_pol_dtls') }}
    where (nullif(trim(PRODUCT_4DIGIT_CODE),'')) is not null
    union all
    select
        md5(upper('HUB_PRODUCT|' || (HUB_PRODUCT_BK__PRODUCT_CODE))) as HUB_PRODUCT_HK
        , cast(null as varchar) as PRODUCT_DISPLAY_NAME
        , PLAN_NAME as PRODUCT_NAME
        , cast(null as varchar) as LINE_OF_BUSINESS
        , cast(null as varchar) as PRODUCT_CATEGORY
        , cast(null as varchar) as PRODUCT_DESCRIPTION
        , cast(null as varchar) as PRODUCT_STATUS
        , cast(null as varchar) as UIN
        , 'BJAZ_HM_MEMBER_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_member_dtls') }}
    where (nullif(trim(PRODUCT_CODE),'')) is not null
    union all
    select
        md5(upper('HUB_PRODUCT|' || (HUB_PRODUCT_BK__SCHEME_CODE_PLAN_ID))) as HUB_PRODUCT_HK
        , PDF_PLAN_DESC as PRODUCT_DISPLAY_NAME
        , PLAN_DESC as PRODUCT_NAME
        , cast(null as varchar) as LINE_OF_BUSINESS
        , cast(null as varchar) as PRODUCT_CATEGORY
        , cast(null as varchar) as PRODUCT_DESCRIPTION
        , ISACTIVE as PRODUCT_STATUS
        , cast(null as varchar) as UIN
        , 'BJAZ_CTNGY_SCHEME_PLANS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ctngy_scheme_plans') }}
    where (nullif('SCHEMEPLAN:' || nullif(trim(SCHEME_CODE),'') || '|' || nullif(trim(PLAN_ID),''), 'SCHEMEPLAN:|')) is not null
    union all
    select
        md5(upper('HUB_PRODUCT|' || (HUB_PRODUCT_BK__PRODUCT_CODE))) as HUB_PRODUCT_HK
        , cast(null as varchar) as PRODUCT_DISPLAY_NAME
        , cast(null as varchar) as PRODUCT_NAME
        , cast(null as varchar) as LINE_OF_BUSINESS
        , cast(null as varchar) as PRODUCT_CATEGORY
        , cast(null as varchar) as PRODUCT_DESCRIPTION
        , cast(null as varchar) as PRODUCT_STATUS
        , UIN_NO as UIN
        , 'BJAZ_CTNGY_GC_CONTROL' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ctngy_gc_control') }}
    where (nullif('PRODUCT:' || nullif(trim(PRODUCT_CODE),''), 'PRODUCT:')) is not null
),

resolved as (
    select
        HUB_PRODUCT_HK,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then PRODUCT_DISPLAY_NAME end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PRODUCT_DISPLAY_NAME end)) as PRODUCT_DISPLAY_NAME,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then PRODUCT_NAME end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PRODUCT_NAME end)) as PRODUCT_NAME,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then LINE_OF_BUSINESS end) as LINE_OF_BUSINESS,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PRODUCT_CATEGORY end) as PRODUCT_CATEGORY,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PRODUCT_DESCRIPTION end) as PRODUCT_DESCRIPTION,
        max(case when SOURCE_RUN = 'opus_health_v2' then PRODUCT_STATUS end) as PRODUCT_STATUS,
        max(case when SOURCE_RUN = 'opus_health_v2' then UIN end) as UIN,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PRODUCT_HK
),

hashed as (
    select
        *,
        case when PRODUCT_DISPLAY_NAME is not null or PRODUCT_NAME is not null or LINE_OF_BUSINESS is not null or PRODUCT_CATEGORY is not null or PRODUCT_DESCRIPTION is not null or PRODUCT_STATUS is not null or UIN is not null
                     then md5(upper(coalesce(cast(PRODUCT_DISPLAY_NAME as varchar), '') || '|' || coalesce(cast(PRODUCT_NAME as varchar), '') || '|' || coalesce(cast(LINE_OF_BUSINESS as varchar), '') || '|' || coalesce(cast(PRODUCT_CATEGORY as varchar), '') || '|' || coalesce(cast(PRODUCT_DESCRIPTION as varchar), '') || '|' || coalesce(cast(PRODUCT_STATUS as varchar), '') || '|' || coalesce(cast(UIN as varchar), '')))
                end as SAT_PRODUCT_DEFINITION_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PRODUCT_HK is not null
  and SAT_PRODUCT_DEFINITION_HASHDIFF is not null
